 const guide=el('section');guide.id='ownerNextGuide';guide.setAttribute('aria-label',"現在の個体の次の操作");const title=el('h3'),body=el('p'),next=el('button');next.className='primary';guide.append(title,body,next);ui.notice.after(guide);let action='identity';
 function current(){return status?.individuals.find(e=>e.profile.individual_id===ui.scope);}
